import{mkdirSync,readFileSync,writeFileSync}from'node:fs';import{chapterCollections,chapterHash,practiceChapters}from'../lib/practice-chapters.ts';import{groupActivities}from'../lib/group-practice.ts';import{learningGoalFor}from'../lib/learning-goals.ts';import{exerciseSetHelp}from'../lib/content-levels.ts';
mkdirSync('outputs/goal-audit-20261101',{recursive:true});const variants=new Map(),activities=[],counts={},ids=new Set(),modes=new Set(),goals=new Set();let instances=0;
for(const activity of groupActivities){let first;for(const row of chapterCollections(activity.id)){const exercises=row.contentUrl?JSON.parse(readFileSync('public'+row.contentUrl)).exercises:row.exercises;if(!exercises.length)continue;for(const e of exercises){const g=learningGoalFor(e);if(!g)throw Error('Missing '+e.exerciseId);instances++;ids.add(e.exerciseId);modes.add(e.mode);goals.add(g.id);counts[e.mode]=(counts[e.mode]||0)+1;const task=e.contentTask,key=[e.mode,g.id,e.componentId,task?.mode||'',task?.teacherWorkflow?.kind||'',e.standardTask?.kind||'',e.standardTask?.basis||'',e.answerPolicy||''].join('|');{const chapter=practiceChapters.find(c=>c.activities.includes(activity.id));const candidate={key,activity:activity.id,collection:row.id,level:row.level,help:exerciseSetHelp(exercises),route:'/'+chapterHash({chapter:chapter.id,activity:activity.id,collection:row.id,level:row.level,help:exerciseSetHelp(exercises)}),exercise:e,goal:g,total:exercises.length,pack:{id:row.pack.id,words:row.pack.words,exerciseTypes:row.pack.exerciseTypes}};if(!variants.has(key))variants.set(key,candidate);first??=candidate;}}}activities.push({id:activity.id,label:activity.label,first});}
const result={instances,uniqueIds:ids.size,modes:[...modes],goals:[...goals],counts,activities,cases:[...new Map([...variants.values(),...activities.map(a=>a.first).filter(Boolean)].map(c=>[c.activity+':'+c.exercise.exerciseId,c])).values()]};writeFileSync('outputs/goal-audit-20261101/inventory.json',JSON.stringify(result,null,2)+'\n');writeFileSync('outputs/goal-audit-20261101/review.tsv','mode\tgoal\tcomponent\tactivity\ttitle\tquestion\tgoal text\n'+result.cases.map(c=>[c.exercise.mode,c.goal.id,c.exercise.componentId,c.activity,c.exercise.title,c.exercise.question||c.exercise.contentTask?.prompt||'',c.goal.learnerText].map(x=>String(x||'').replace(/[\t\n]/g,' ')).join('\t')).join('\n')+'\n');console.log({instances,uniqueIds:ids.size,modes:modes.size,goals:goals.size,activities:activities.length,variants:variants.size});
